const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
let mount,poll,options,cleared=0,visits=[],response,copied="";
const memory=new Map(),feedback={textContent:''},state={textContent:''},row={dataset:{turnId:'turn'},querySelector:()=>state};
const input={value:''},requestKey={value:'new-key'},form={elements:{namedItem:n=>n==='input'?input:requestKey},querySelector:()=>feedback};
const copyButton={},adoptButton={},claimFeedback={textContent:''},claim={dataset:{kind:'AI解释',text:'选中的解释'},querySelector:s=>s==='[data-study-copy]'?copyButton:s==='[data-study-adopt]'?adoptButton:claimFeedback,querySelectorAll:()=>[{textContent:'冻结依据',href:'http://localhost/evidence/snapshot?position=1'}]};
const root={dataset:{session:'session',question:'question'},querySelector:s=>s==='#question-study-ask'?form:feedback,querySelectorAll:s=>s==='[data-turn-id]'?[row]:s==='.question-study-claim'?[claim]:[form]};
const storage={getItem:k=>memory.get(k),setItem:(k,v)=>memory.set(k,v),removeItem:k=>memory.delete(k)};
memory.set('cwp-question-study-draft:session',JSON.stringify({input:'保留的下一问',requestKey:'stable-key'}));
const window={CWPViews:{define:fn=>mount=fn},CWPForms:{bind:(f,o,opt)=>options=opt},CWPPrivate:{clear:()=>cleared++},CWPNavigation:{visit:async v=>visits.push(v)}};
const events=new Map(),scope={signal:{aborted:false},on:(n,e,fn)=>events.set(n,fn),interval:fn=>poll=fn,fetch:async()=>response};
vm.runInNewContext(fs.readFileSync('static/question-study.js','utf8'),{window,sessionStorage:storage,document:{hidden:false},navigator:{clipboard:{writeText:async text=>copied=text}},location:{pathname:'/questions/question/study'},encodeURIComponent,Array,JSON});
mount({querySelector:()=>root},scope);
assert.equal(input.value,'保留的下一问');assert.equal(requestKey.value,'stable-key');
input.value='修改后的下一问';events.get(input)();assert.match(memory.get('cwp-question-study-draft:session'),/修改后的下一问/);
(async()=>{
 response={ok:true,status:200,json:async()=>({revision:7,turns:[{ID:'turn',State:'accepted'}]})};await poll();
 assert.equal(state.textContent,'accepted');assert.equal(input.value,'修改后的下一问');assert.equal(requestKey.value,'stable-key');assert.ok(memory.size);
 response={ok:false,status:409};await poll();assert.equal(input.value,'修改后的下一问');
 await events.get(copyButton)();assert.match(copied,/选中的解释/);assert.match(copied,/AI 辅助问答草稿/);assert.match(copied,/snapshot\?position=1/);assert.equal(visits.length,0);
 await events.get(adoptButton)();assert.match(memory.get('cwp-question-study-adopt:question'),/选中的解释/);assert.equal(visits.pop(),'/questions/question#question-note');
 response={ok:false,status:401};await poll();assert.equal(cleared,1);assert.deepEqual(visits,['/login']);
 scope.signal.aborted=true;response={ok:true,status:200,json:async()=>({turns:[{ID:'turn',State:'bad'}]})};await poll();assert.equal(state.textContent,'accepted');
 options.success();assert.equal(memory.has('cwp-question-study-draft:session'),false);
 console.log('question study draft identity, polling, authorization and disposal passed');
})().catch(error=>{console.error(error);process.exitCode=1;});
